Item.method_code:
const item = aras.itemsCache.getItemByXPath("//Item[@id='"+itemId+"']");
const isTemp = item.getAttribute("isTemp");
const result = {
    valid : true
};

if(isTemp !== "1" && !value)
{
    result.valid = false;
    result.validationMessage = aras.getResource('', 'item_methods_ex.field_required_provide_value', options.itemType.Property.find(o => o.name === name).label);
}

return result;
